/* App.css - Define variables once */
:root {
 --react: #61dafb;
 --react-2: #0ea5e9;
 --bg: #07111f;
 --card: rgba(15, 31, 51, 0.88);
 --muted: #94a3b8;
 --success: #22c55e;
 --border: rgba(97, 218, 251, 0.16);
}

/* Use variables everywhere */
.lesson-card {
 background: var(--card);
 border: 1px solid var(--border);
 border-radius: 20px;
 padding: 22px;
}

.lesson-title {
 color: var(--react);
 font-size: 20px;
}

/* Change theme by changing variables - dark to light mode */
.light-mode {
 --bg: #ffffff;
 --card: #f8fafc;
 --muted: #64748b;
}

import './App.css'; // Contains :root variables

function LessonCard({ status }) {
 // Dynamic style using CSS variable + status prop
 const cardStyle = {
 background: 'var(--card)', // From CSS variable
 border: `1px solid ${status==='completed'? 'var(--success)' : 'var(--border)'}`,
 borderRadius: '20px',
 padding: '22px',
 backdropFilter: 'blur(18px)', // Glassmorphism from your dashboard!
 WebkitBackdropFilter: 'blur(18px)'
 };

 return (
 <div style={cardStyle} className="lesson-card-hover">
 <h3 style={{color: 'var(--react)'}}>Lesson Title</h3>
 <p style={{color: 'var(--muted)'}}>What you will learn</p>
 </div>
 );
}
// CSS variables + inline dynamic + className = your dashboard's exact pattern

function GlassCard() {
 const glassStyle = {
 background: 'rgba(15, 31, 51, 0.82)', // Semi-transparent - key!
 backdropFilter: 'blur(18px)', // Blur behind card - key!
 WebkitBackdropFilter: 'blur(18px)', // For Safari
 border: '1px solid rgba(97, 218, 251, 0.16)', // Subtle colored border
 borderRadius: '20px',
 padding: '22px',
 boxShadow: '0 24px 60px rgba(0,0,0,0.48), 0 0 0 1px rgba(97,218,251,0.08) inset', // Depth + inner glow
 };

 return (
 <div style={{background: 'linear-gradient(135deg, #020617 0%, #07111f 45%, #0a1a2f 100%)', padding: '40px'}}>
 <div style={glassStyle}>
 <h3 style={{color: '#61dafb'}}>Glassmorphism Card</h3>
 <p style={{color: '#94a3b8'}}>This is how your dashboard looks premium - blur + transparency + border + shadow</p>
 </div>
 </div>
 );
}
// Try removing backdrop-filter - loses premium blur effect!
// Try making background solid #0f1f33 - loses glass transparency!

function LessonCard({ status, progress }) {
 // Dynamic values based on props
 const badgeConfig = {
 completed: { color: '#4ade80', bg: 'rgba(34,197,94,0.14)', text: 'COMPLETED' },
 current: { color: '#61dafb', bg: 'rgba(97,218,251,0.14)', text: 'CURRENT' },
 locked: { color: '#94a3b8', bg: 'rgba(148,163,184,0.14)', text: 'LOCKED' }
 };

 const config = badgeConfig[status] || badgeConfig.locked;

 return (
 <div style={{background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '20px', padding: '22px'}}>
 <div style={{display: 'flex', justifyContent: 'space-between'}}>
 <span>LESSON 02</span>
 <span style={{color: config.color, background: config.bg, padding: '5px 10px', borderRadius: '999px', fontSize: '10px', fontWeight: '800'}}>
 {config.text}
 </span>
 </div>
 {/* Dynamic width based on progress prop */}
 <div style={{height: '6px', background: 'rgba(148,163,184,0.12)', borderRadius: '99px', marginTop: '12px'}}>
 <div style={{width: `${progress}%`, height: '100%', background: `linear-gradient(90deg, ${config.color}, #8b5cf6)`, borderRadius: '99px', transition: 'width 0.6s ease'}}></div>
 </div>
 </div>
 );
}

function App() {
 return (
 <>
 <LessonCard status="completed" progress={100} />
 <LessonCard status="current" progress={60} />
 <LessonCard status="locked" progress={0} />
 </>
 );
}
// Same component, different colors and widths based on props - dynamic styling!

